def dedup(lista):
    seen = set()
    resultado = []
    for elemento in lista:
        if elemento not in seen:
            seen.add(elemento)
            resultado.append(elemento)
    return resultado

def binaria(lista, x):
    izq = 0
    der = len(lista) - 1

    while izq <= der:
        medio = (izq + der) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izq = medio + 1
        else:
            der = medio - 1

    return -1

def anidar(plano: dict) -> dict:
    def _anidar(d: dict, prefix: str = "") -> dict:
        resultado = {}
        for clave, valor in d.items():
            if "." in clave:
                partes = clave.split(".")
                nuevo_prefix = prefix + partes[0]
                resultado[nuevo_prefix] = _anidar({partes[1]: valor}, nuevo_prefix)
            else:
                if prefix:
                    resultado[prefix][clave] = valor
                else:
                    resultado[clave] = valor
        return resultado

    return _anidar(plano)

def comprimir(s: str) -> str:
    if not s:
        return ""

    resultado = []
    contador = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            contador += 1
        else:
            resultado.append(s[i - 1] + str(contador))
            contador = 1

    resultado.append(s[-1] + str(contador))
    return "".join(resultado)

def promedio_movil(nums, ventana):
