    return [sum(nums[i:i+ventana]) / ventana for i in range(len(nums) - ventana + 1)]

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a una cadena legible usando múltiplos de 1024.

    Args:
        n: Número de bytes.

    Returns:
        Cadena con el valor formateado (ej: '1.5 KB', '2 GB').
    """
    if n < 1024:
        return f"{n} B"
    elif n < 1024 ** 2:
        return f"{n / 1024:.1f} KB"
    elif n < 1024 ** 3:
        return f"{n / (1024 ** 2):.1f} MB"
    else:
        return f"{n / (1024 ** 3):.1f} GB"

def parsear_query(s: str) -> dict:
    if not s:
        return {}
    result = {}
    for pair in s.split('&'):
        if '=' in pair:
            key, value = pair.split('=', 1)
            result[key] = value
        else:
            result[pair] = ''
    return result

def contar_islas(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    filas = len(grid)
    columnas = len(grid[0])
    visitados = [[False] * columnas for _ in range(filas)]

    def dfs(fila: int, col: int) -> None:
        visitados[fila][col] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nueva_fila, nueva_col = fila + dr, col + dc
            if (0 <= nueva_fila < filas and 0 <= nueva_col < columnas and
                    not visitados[nueva_fila][nueva_col] and grid[nueva_fila][nueva_col] == 1):
                dfs(nueva_fila, nueva_col)

    islas = 0
    for i in range(filas):
        for j in range(columnas):
            if grid[i][j] == 1 and not visitados[i][j]:
                islas += 1
                dfs(i, j)

    return islas

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # borrado
                    dp[i][j - 1],    # inserción
                    dp[i - 1][j - 1] # sustitución
                )
    return dp[n][m]

import re

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not re.search(r'[A-Z]', p):
        return False
    if not re.search(r'[a-z]', p):
        return False
    if not re.search(r'[0-9]', p):
        return False
    if not re.search(r'[^A-Za-z0-9]', p):
        return False
    return True

