def titular(s: str) -> str:
    palabras = s.split()
    mayusculas = {'de', 'del', 'la', 'las', 'el', 'los', 'y'}
    resultado = []
    for i, palabra in enumerate(palabras):
        if i == 0:
            resultado.append(palabra.capitalize())
        elif palabra.lower() in mayusculas:
            resultado.append(palabra.lower())
        else:
            resultado.append(palabra.capitalize())
    return ' '.join(resultado)

def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            resultado.append(elemento)
    return resultado

def sumar_romanos(a: str, b: str) -> str:
    """Suma dos números romanos y devuelve el resultado en romano."""
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    inverso = {v: k for k, v in valores.items()}

    def romano_a_entero(s: str) -> int:
        total = 0
        prev = 0
        for char in reversed(s):
            curr = valores[char]
            if curr < prev:
                total -= curr
            else:
                total += curr
            prev = curr
        return total

    def entero_a_romano(n: int) -> str:
        if n == 0:
            return ""
        resultado = []
        while n > 0:
            for simbolo, valor in inverso.items():
                if valor <= n:
                    resultado.append(simbolo)
                    n -= valor
                    break
        return "".join(reversed(resultado))

    return entero_a_romano(romano_a_entero(a) + romano_a_entero(b))

def obtener(d, camino, defecto=None):
    partes = camino.split('.')
    valor = d
    for parte in partes:
        if isinstance(valor, dict) and parte in valor:
            valor = valor[parte]
        else:
            return defecto
    return valor

def con_reintentos(fn, veces):
